Quiero que me digas que opinas de esta implementacion de store con optimismo, y si ves algo que se pueda mejorar.

Actualemnte todo funciona como debe, lo unico que me gustaria saber es si hay algo que se pueda mejorar en cuanto a independencia de responsabilidades, ya que siento que el store esta haciendo mucho trabajo y el servicio muy poco.

```ts next-bound-frontend/src/app/store/userStore.ts
import { computed, effect, inject } from "@angular/core";
import {
  addEntities,
  removeEntity,
  setAllEntities,
  updateEntity,
  withEntities,
} from "@ngrx/signals/entities";
import {
  getState,
  patchState,
  signalStore,
  withComputed,
  withHooks,
  withMethods,
  withState,
} from "@ngrx/signals";

import { OptimisticService } from "../shared/services/optimistic.service";
import { AdmUserService } from "../administration/services/adm-user.service";
import { NotificationService } from "../shared/services/notification.service";

export interface User {
  id: number;
  username: string;
  token: string;
  firstName: string;
  lastName: string;
  password: string;
  createdAt: string;
}

interface UserState {
  state: "loading" | "loaded" | "error";
}

const initialState: UserState = {
  state: "loading",
};

export const userStore = signalStore(
  { providedIn: "root" },
  withState(initialState),
  withEntities<User>(),
  withComputed(({ entities }) => ({
    userCount: computed(() => entities().length),
    userById: computed(
      () => (id: number) => entities().find((u) => u.id === id),
    ),
  })),
  withMethods(
    (
      store,
      userService = inject(AdmUserService),
      optimisticService = inject(OptimisticService),
      notificationService = inject(NotificationService),
    ) => ({
      setUsers(users: User[]): void {
        patchState(store, setAllEntities(users));
        patchState(store, { state: "loaded" });
      },

      loadUsers(): void {
        patchState(store, { state: "loading" });
        userService.fetchUsers().subscribe({
          next: (resp) => {
            patchState(store, setAllEntities(resp));
            patchState(store, { state: "loaded" });
          },
        });
      },

      addUser(user: Omit<User, "id" | "token">): void {
        const tempId = Date.now();
        const tempUser = { ...user, id: tempId, token: "" };
        patchState(store, addEntities([tempUser]));

        userService.addUser(user).subscribe({
          next: (newUser) => {
            patchState(store, updateEntity({ id: tempId, changes: newUser }));
          },
          error: (err) => {
            patchState(store, removeEntity(tempId));
            optimisticService.setErrorState(tempId, err.msg);
          },
        });
      },

      updateUser(user: Partial<User> & { id: number }): void {
        // const originalUser = store.entities().find((u) => u.id === user.id);
        const originalUser = store.userById()(user.id);
        if (!originalUser) {
          // Handle the case where the original user is not found
          return;
        }

        patchState(store, updateEntity({ id: user.id, changes: user }));

        optimisticService.setLoadingState(user.id, {
          isLoading: true,
          operation: "updating",
        });

        userService
          .updateUser(user as Omit<User, "token" | "password">)
          .subscribe({
            next: (updatedUser) => {
              patchState(
                store,
                updateEntity({ id: updatedUser.id, changes: updatedUser }),
              );
            },
            error: (err) => {
              patchState(
                store,
                updateEntity({ id: user.id, changes: originalUser }),
              );
              notificationService.showToast(
                "error",
                `${originalUser.username}`,
                "Error al eliminar el usuario",
              );
            },
          })
          .add(() => {
            optimisticService.setLoadingState(user.id, { isLoading: false });
          });
      },

      removeUser(userId: number): void {
        optimisticService.setLoadingState(userId, {
          isLoading: true,
          operation: "deleting",
        });
        userService
          .deleteUser(userId)
          .subscribe({
            next: () => {
              patchState(store, removeEntity(userId));
            },
            error: (err) => {
              console.log(err);
              optimisticService.setErrorState(userId, err.message);
            },
          })
          .add(() => {
            optimisticService.setLoadingState(userId, { isLoading: false });
          });
      },
    }),
  ),
  withHooks({
    onInit(store) {
      store.loadUsers();

      effect(() => {
        const state = getState(store);
        console.log(state);
      });
    },
  }),
);
```

```ts next-bound-frontend/src/app/administration/services/adm-user.service.ts
import { HttpClient } from "@angular/common/http";
import { inject, Injectable } from "@angular/core";

import { User } from "src/app/store/userStore";
import { environment } from "src/environments/environment.development";

@Injectable({
  providedIn: "root",
})
export class AdmUserService {
  constructor() {}

  private http = inject(HttpClient);

  fetchUsers() {
    return this.http.get<User[]>(`${environment.apiUrl}/user`);
  }

  getUser(id: number) {
    return this.http.get<User>(`${environment.apiUrl}/user/${id}`);
  }

  addUser(data: Omit<User, "id" | "token">) {
    return this.http.post<User>(`${environment.apiUrl}/auth/register`, data);
  }

  updateUser(data: Omit<User, "token" | "password">) {
    return this.http.patch<User>(`${environment.apiUrl}/user/${data.id}`, data);
  }

  deleteUser(id: number) {
    return this.http.delete(`${environment.apiUrl}/users/${id}`);
  }

  getToken() {
    return localStorage.getItem("token");
  }
}
